CREATE TABLE public.indicadores_members (user_id uuid PRIMARY KEY REFERENCES public.profiles(id), role text NOT NULL DEFAULT 'viewer' CHECK(role IN ('viewer','editor','admin')));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.indicadores_members TO authenticated; GRANT ALL ON public.indicadores_members TO service_role;
ALTER TABLE public.indicadores_members ENABLE ROW LEVEL SECURITY;
INSERT INTO public.indicadores_members(user_id,role) SELECT user_id,role FROM public.mytosis_members ON CONFLICT DO NOTHING;
CREATE OR REPLACE FUNCTION public.indicadores_role(_user_id uuid) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN public.is_erp_admin(_user_id) THEN 'admin' ELSE coalesce((SELECT role FROM public.indicadores_members WHERE user_id=_user_id),(SELECT 'viewer' FROM public.user_app_access WHERE user_id=_user_id AND app_key='indicadores')) END $$;
REVOKE ALL ON FUNCTION public.indicadores_role(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.indicadores_role(uuid) TO authenticated,service_role;
CREATE POLICY members_read ON public.indicadores_members FOR SELECT TO authenticated USING(user_id=auth.uid() OR public.indicadores_role(auth.uid())='admin');
CREATE POLICY members_manage ON public.indicadores_members FOR ALL TO authenticated USING(public.is_erp_admin(auth.uid())) WITH CHECK(public.is_erp_admin(auth.uid()));
CREATE TABLE public.indicadores_cycles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, starts_on date NOT NULL, ends_on date NOT NULL, archived boolean NOT NULL DEFAULT false, created_by uuid NOT NULL DEFAULT auth.uid() REFERENCES public.profiles(id), CHECK(ends_on>=starts_on));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.indicadores_cycles TO authenticated; GRANT ALL ON public.indicadores_cycles TO service_role;
ALTER TABLE public.indicadores_cycles ENABLE ROW LEVEL SECURITY;
CREATE POLICY cycles_read ON public.indicadores_cycles FOR SELECT TO authenticated USING(public.indicadores_role(auth.uid()) IS NOT NULL);
CREATE POLICY cycles_manage ON public.indicadores_cycles FOR ALL TO authenticated USING(public.indicadores_role(auth.uid()) IN ('admin','editor')) WITH CHECK(public.indicadores_role(auth.uid()) IN ('admin','editor'));
CREATE TABLE public.indicadores_objectives(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, description text, parent_id uuid REFERENCES public.indicadores_objectives(id), cycle_id uuid REFERENCES public.indicadores_cycles(id), scope text NOT NULL DEFAULT 'empresa' CHECK(scope IN ('empresa','departamento','equipe','individual')), alignment_name text, responsible_id uuid REFERENCES public.profiles(id), confidential boolean NOT NULL DEFAULT false, allowed_user_ids uuid[] NOT NULL DEFAULT '{}', created_by uuid NOT NULL DEFAULT auth.uid() REFERENCES public.profiles(id), created_at timestamptz NOT NULL DEFAULT now(), legacy_node_id uuid UNIQUE REFERENCES public.mytosis_nodes(id));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.indicadores_objectives TO authenticated; GRANT ALL ON public.indicadores_objectives TO service_role;
ALTER TABLE public.indicadores_objectives ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.indicadores_objective_visible(_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ WITH RECURSIVE ancestors AS (SELECT id,parent_id,confidential,allowed_user_ids FROM public.indicadores_objectives WHERE id=_id UNION SELECT o.id,o.parent_id,o.confidential,o.allowed_user_ids FROM public.indicadores_objectives o JOIN ancestors a ON o.id=a.parent_id) SELECT public.indicadores_role(auth.uid()) IS NOT NULL AND (public.indicadores_role(auth.uid())='admin' OR NOT EXISTS(SELECT 1 FROM ancestors WHERE confidential AND NOT auth.uid()=ANY(allowed_user_ids))) $$;
REVOKE ALL ON FUNCTION public.indicadores_objective_visible(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.indicadores_objective_visible(uuid) TO authenticated,service_role;
CREATE POLICY objectives_read ON public.indicadores_objectives FOR SELECT TO authenticated USING(public.indicadores_objective_visible(id));
CREATE POLICY objectives_insert ON public.indicadores_objectives FOR INSERT TO authenticated WITH CHECK(public.indicadores_role(auth.uid()) IN ('admin','editor') AND created_by=auth.uid() AND (parent_id IS NULL OR public.indicadores_objective_visible(parent_id)) AND (NOT confidential OR public.indicadores_role(auth.uid())='admin'));
CREATE POLICY objectives_update ON public.indicadores_objectives FOR UPDATE TO authenticated USING(public.indicadores_objective_visible(id) AND public.indicadores_role(auth.uid()) IN ('admin','editor')) WITH CHECK(public.indicadores_objective_visible(id));
CREATE POLICY objectives_delete ON public.indicadores_objectives FOR DELETE TO authenticated USING(public.indicadores_objective_visible(id) AND public.indicadores_role(auth.uid()) IN ('admin','editor'));
CREATE TABLE public.indicadores_metrics(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), title text NOT NULL, kind text NOT NULL CHECK(kind IN ('kr','kpi')), objective_id uuid REFERENCES public.indicadores_objectives(id), responsible_id uuid NOT NULL REFERENCES public.profiles(id), measure text NOT NULL DEFAULT 'percentage' CHECK(measure IN ('percentage','number','currency','binary')), initial_value numeric NOT NULL DEFAULT 0, target_value numeric NOT NULL DEFAULT 100, current_value numeric NOT NULL DEFAULT 0, confidence text NOT NULL DEFAULT 'on_track' CHECK(confidence IN ('on_track','at_risk','late')), due_on date, unit text NOT NULL DEFAULT '', created_by uuid NOT NULL DEFAULT auth.uid() REFERENCES public.profiles(id), created_at timestamptz NOT NULL DEFAULT now(), legacy_kpi_id uuid UNIQUE REFERENCES public.mytosis_kpis(id), CHECK(kind='kpi' OR objective_id IS NOT NULL));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.indicadores_metrics TO authenticated; GRANT ALL ON public.indicadores_metrics TO service_role;
ALTER TABLE public.indicadores_metrics ENABLE ROW LEVEL SECURITY;
CREATE OR REPLACE FUNCTION public.indicadores_metric_visible(_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.indicadores_role(auth.uid()) IS NOT NULL AND EXISTS(SELECT 1 FROM public.indicadores_metrics m WHERE m.id=_id AND (m.objective_id IS NULL OR public.indicadores_objective_visible(m.objective_id))) $$;
REVOKE ALL ON FUNCTION public.indicadores_metric_visible(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.indicadores_metric_visible(uuid) TO authenticated,service_role;
CREATE POLICY metrics_read ON public.indicadores_metrics FOR SELECT TO authenticated USING(public.indicadores_metric_visible(id));
CREATE POLICY metrics_insert ON public.indicadores_metrics FOR INSERT TO authenticated WITH CHECK(public.indicadores_role(auth.uid()) IN ('admin','editor') AND created_by=auth.uid() AND (objective_id IS NULL OR public.indicadores_objective_visible(objective_id)));
CREATE POLICY metrics_update ON public.indicadores_metrics FOR UPDATE TO authenticated USING(public.indicadores_metric_visible(id) AND public.indicadores_role(auth.uid()) IN ('admin','editor')) WITH CHECK(public.indicadores_metric_visible(id));
CREATE POLICY metrics_delete ON public.indicadores_metrics FOR DELETE TO authenticated USING(public.indicadores_metric_visible(id) AND public.indicadores_role(auth.uid()) IN ('admin','editor'));
CREATE TABLE public.indicadores_checkins(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), metric_id uuid NOT NULL REFERENCES public.indicadores_metrics(id), value numeric NOT NULL, confidence text NOT NULL CHECK(confidence IN ('on_track','at_risk','late')), comment text NOT NULL DEFAULT '', recorded_by uuid NOT NULL DEFAULT auth.uid() REFERENCES public.profiles(id), recorded_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.indicadores_checkins TO authenticated; GRANT ALL ON public.indicadores_checkins TO service_role;
ALTER TABLE public.indicadores_checkins ENABLE ROW LEVEL SECURITY;
CREATE POLICY checkins_read ON public.indicadores_checkins FOR SELECT TO authenticated USING(public.indicadores_metric_visible(metric_id));
CREATE OR REPLACE FUNCTION public.indicadores_checkin(_metric_id uuid,_value numeric,_confidence text,_comment text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE m public.indicadores_metrics; result uuid; BEGIN SELECT * INTO m FROM public.indicadores_metrics WHERE id=_metric_id FOR UPDATE; IF auth.uid() IS NULL OR NOT public.indicadores_metric_visible(_metric_id) OR (m.responsible_id<>auth.uid() AND public.indicadores_role(auth.uid())<>'admin') THEN RAISE EXCEPTION 'Sem permissão para atualizar este indicador.'; END IF; IF m.objective_id IS NOT NULL AND EXISTS(SELECT 1 FROM public.indicadores_objectives o JOIN public.indicadores_cycles c ON c.id=o.cycle_id WHERE o.id=m.objective_id AND c.archived) THEN RAISE EXCEPTION 'O ciclo está arquivado.'; END IF; IF _confidence NOT IN ('on_track','at_risk','late') OR _value IS NULL OR (m.measure='binary' AND _value NOT IN (0,1)) THEN RAISE EXCEPTION 'Valor ou confiança inválidos.'; END IF; INSERT INTO public.indicadores_checkins(metric_id,value,confidence,comment,recorded_by) VALUES(_metric_id,_value,_confidence,coalesce(_comment,''),auth.uid()) RETURNING id INTO result; UPDATE public.indicadores_metrics SET current_value=_value,confidence=_confidence WHERE id=_metric_id; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.indicadores_checkin(uuid,numeric,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.indicadores_checkin(uuid,numeric,text,text) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.indicadores_guard_objective() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND (NEW.confidential IS DISTINCT FROM OLD.confidential OR NEW.allowed_user_ids IS DISTINCT FROM OLD.allowed_user_ids) AND public.indicadores_role(auth.uid())<>'admin' THEN RAISE EXCEPTION 'Somente Admin define visibilidade.'; END IF; IF NEW.parent_id IS NOT NULL AND EXISTS(WITH RECURSIVE parents AS (SELECT id,parent_id FROM public.indicadores_objectives WHERE id=NEW.parent_id UNION SELECT o.id,o.parent_id FROM public.indicadores_objectives o JOIN parents p ON o.id=p.parent_id) SELECT 1 FROM parents WHERE id=NEW.id) THEN RAISE EXCEPTION 'O alinhamento não pode formar um ciclo.'; END IF; IF NEW.parent_id IS NOT NULL AND NOT public.indicadores_objective_visible(NEW.parent_id) THEN RAISE EXCEPTION 'Objetivo superior indisponível.'; END IF; RETURN NEW; END $$;
CREATE TRIGGER indicadores_objective_guard BEFORE INSERT OR UPDATE ON public.indicadores_objectives FOR EACH ROW EXECUTE FUNCTION public.indicadores_guard_objective();
INSERT INTO public.indicadores_objectives(id,title,description,parent_id,responsible_id,created_by,created_at,legacy_node_id) SELECT id,title,description,parent_id,responsible_id,coalesce(created_by,responsible_id),created_at,id FROM public.mytosis_nodes WHERE NOT is_process AND kind='objective';
INSERT INTO public.indicadores_metrics(title,kind,responsible_id,unit,target_value,created_by,legacy_kpi_id) SELECT name,'kpi',responsible_id,unit,target,created_by,id FROM public.mytosis_kpis;
CREATE INDEX indicadores_metrics_objective ON public.indicadores_metrics(objective_id);
CREATE INDEX indicadores_checkins_metric_time ON public.indicadores_checkins(metric_id,recorded_at DESC);